attributes:
onClick={() =>
            run(
              () =>
                db.editions.update(edition.id, {
                  deleted: false,
                  updatedAt: now(),
                }),
              "Édition restaurée.",
            )
          }

onClick={() =>
              run(
                () =>
                  db.editions.update(edition.id, {
                    deleted: true,
                    updatedAt: now(),
                  }),
                "Édition déplacée dans la corbeille.",
              )
            }

aria-label={
                theme === "light"
                  ? "Activer le mode sombre"
                  : "Activer le mode clair"
              }

onClick={() =>
                run(() =>
                  db.preferences.put({
                    key: "theme",
                    value: theme === "light" ? "dark" : "light",
                  }),
                )
              }

onClick={() =>
                            run(
                              localBackup,
                              "Archive de sauvegarde téléchargée.",
                            )
                          }

onClick={() =>
                          run(async () => {
                            const persisted =
                              await navigator.storage?.persist();
                            setStorage({ ...storage, persisted });
                            setToast(
                              persisted
                                ? "Stockage persistant accordé par le navigateur."
                                : "Le navigateur n’a pas accordé le stockage persistant.",
                            );
                          })
                        }

onClick={() =>
                                    run(async () => {
                                      await remote.restore(session, s.id);
                                    }, "Sauvegarde cloud restaurée par fusion. Les notes en conflit sont conservées.")
                                  }

onClick={() =>
                              run(async () => {
                                const { error } = await cloud.auth.signOut({
                                  scope: "local",
                                });
                                if (error) throw error;
                                setSnapshots([]);
                                setCloudStatus(
                                  "Aucune sauvegarde cloud active",
                                );
                              }, "Déconnecté. La bibliothèque locale est conservée.")
                            }

onClick={() =>
                  run(async () => {
                    const result = await restoreBackup(db, restoration);
                    setRestoration(null);
                    setToast(
                      `${result.added} éditions restaurées · ${result.conflicts} notes en conflit conservées.`,
                    );
                  })
                }

onClick={() =>
                    changeFilter(() => {
                      setQuery("");
                      setCategory("");
                      setGroup("");
                      setStatus("");
                    })
                  }

onClick={() =>
                          onReading(current.edition.id, current.article.id, {
                            favorite: !stateOf(
                              current.edition.id,
                              current.article.id,
                            )?.favorite,
                          })
                        }

onClick={() =>
                          onReading(current.edition.id, current.article.id, {
                            read: !stateOf(
                              current.edition.id,
                              current.article.id,
                            )?.read,
                          })
                        }

disabled={
              busy ||
              candidates.some(
                (c) =>
                  !dayKeyOf(
                    inCollection(
                      {
                        ...c.edition,
                        date: metadata[c.edition.id]
                          ? metadata[c.edition.id].date || null
                          : c.edition.date,
                      },
                      destinations[c.edition.id] ||
                        c.edition.collection ||
                        "library",
                    ),
                  ) &&
                  choices[c.edition.id] === "version" &&
                  !parents[c.edition.id],
              )
            }

onClick={() =>
            run(
              () =>
                db.transaction("rw", db.editions, async () => {
                  const ids = day
                    ? day.versions.map((v) => v.edition.id)
                    : [edition.id];
                  const updatedAt = now();
                  for (const id of ids)
                    await db.editions.update(id, {
                      archived: !edition.archived,
                      updatedAt,
                    });
                }),
              edition.archived ? "Édition désarchivée." : "Édition archivée.",
            )
          }

onClick={() =>
            run(async () => {
              await db.preferences.put({
                key: `reader-trust-${edition.id}`,
                value: "safe",
              });
              setMode("safe");
            })
          }

onClick={() => {
                  if (mode !== "interactive") setConfirm(true);
                  else
                    run(async () => {
                      await db.preferences.put({
                        key: `reader-trust-${edition.id}`,
                        value: "safe",
                      });
                      setMode("safe");
                    });
                }}

onClick={() =>
                          run(() =>
                            db.reading(edition.id, a.id, {
                              favorite: !states.find(
                                (s) =>
                                  s.editionId === edition.id &&
                                  s.articleId === a.id,
                              )?.favorite,
                            }),
                          )
                        }

onClick={() =>
                          run(() =>
                            db.reading(edition.id, a.id, {
                              read: !states.find(
                                (s) =>
                                  s.editionId === edition.id &&
                                  s.articleId === a.id,
                              )?.read,
                            }),
                          )
                        }

onClick={() =>
                    run(async () => {
                      await db.preferences.put({
                        key: `reader-trust-${edition.id}`,
                        value: "interactive",
                      });
                      setMode("interactive");
                      setConfirm(false);
                    })
                  }

title={
        error ||
        `${detail}${!autoSync && owner ? " · Synchronisation automatique désactivée" : ""}`
      }

onClick={() =>
          download(
            new Blob([JSON.stringify(entries, null, 2)], {
              type: "application/json",
            }),
            "journal360-diagnostic-expurge.json",
          )
        }

onClick={() =>
                run(async () => {
                  download(
                    blobOf(
                      new TextEncoder().encode(JSON.stringify(p, null, 2)),
                      "application/json",
                    ),
                    p.documentId + ".json",
                  );
                })
              }

onClick={() =>
                run(async () => {
                  download(
                    blobOf(
                      new TextEncoder().encode(renderFutureHTML(p)),
                      "text/html",
                    ),
                    p.documentId + ".html",
                  );
                })
              }

onClick={() =>
                run(async () => {
                  if (!chosen || !activeVersion) return;
                  const o = await futureDb.originals.get(chosen);
                  if (o)
                    download(
                      blobOf(
                        o.bytes,
                        activeVersion.kind === "json"
                          ? "application/json"
                          : "text/html",
                      ),
                      activeVersion.filename,
                    );
                })
              }

onClick={() =>
                  run(async () =>
                    setPreview(
                      radarReaderHTML(
                        new TextEncoder().encode(
                          renderFutureHTML(p).replace(
                            "</head>",
                            "<style>*,*::before,*::after{animation:none!important;transition:none!important}</style></head>",
                          ),
                        ),
                      ),
                    ),
                  )
                }

onClick={() =>
              run(async () => {
                download(
                  await exportFutureBackup(futureDb),
                  "Le-Futur-" + new Date().toISOString().slice(0, 10) + ".zip",
                );
                setMessage(
                  "Sauvegarde exportée : elle contient vos originaux et vos notes privés.",
                );
              })
            }

ref={(el) => {
                        if (el) cardRefs.current.set(d.documentId, el);
                        else cardRefs.current.delete(d.documentId);
                      }}

onClick={() =>
                  run(async () => {
                    const count = await restoreFutureBackup(futureDb, archive);
                    setArchive(null);
                    setMessage(
                      `${count} révisions restaurées. États personnels fusionnés.`,
                    );
                  })
                }

onClick={async () => {
              setBusy(true);
              setError("");
              try {
                const result = await futureDb.importBatch(
                  eligible.map((r) => r.candidate),
                  new Set(
                    eligible
                      .filter((r) =>
                        confirmed.has(confirmationKey(r.candidate)),
                      )
                      .map((r) => r.candidate.payload!.documentId),
                  ),
                  migrations,
                );
                const ignored =
                  result.ignored +
                  rows.filter((r) => r.preview.status === "duplicate").length;
                onDone(
                  `${result.added} dossiers ou révisions importés · ${ignored} doublon${ignored > 1 ? "s" : ""} ignoré${ignored > 1 ? "s" : ""}. Les fichiers incompatibles n’ont pas été importés.`,
                );
              } catch (e) {
                setError(e instanceof Error ? e.message : String(e));
              } finally {
                setBusy(false);
              }
            }}

onClick={() =>
                  onOpen(
                    i.origin.id,
                    i.origin.unified!.items.find(
                      (a) => a.eventId === i.eventId,
                    )!.id,
                  )
                }

onClick={() => {
                  try {
                    const checked = validateFuture(p);
                    download(
                      new Blob([JSON.stringify(checked, null, 2)], {
                        type: "application/json",
                      }),
                      "Future-" + p.documentId + ".json",
                    );
                    setError("");
                  } catch (e) {
                    setError(String(e));
                  }
                }}
